const MONTHS = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC']
const DAYS = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
const THEMES = {
  custom: ['#102033', '#214A4F', '#F6EFE7', '#D69A5E', '#D8C6AD', '#5C7478'],
  ember: ['#102033', '#214A4F', '#F6EFE7', '#D69A5E', '#D8C6AD', '#5C7478'],
  classicLight: ['#F8F5EE', '#FFFFFF', '#111111', '#111111', '#111111', '#D2D2D2'],
  classicDark: ['#050607', '#171A1F', '#FFFFFF', '#FFFFFF', '#FFFFFF', '#4C5563'],
  sepia: ['#F1E3C6', '#D8B982', '#2D2115', '#8A4F23', '#6B4A2C', '#BFA77F'],
  forest: ['#0F2A22', '#23483A', '#F1F5DD', '#D8A84E', '#BDD3A6', '#587264'],
  ocean: ['#08233A', '#14556B', '#EEF8F6', '#7CC8C2', '#B8DDE0', '#486F7B'],
  plum: ['#26172F', '#56395E', '#FFF3EA', '#D8A1B8', '#D8C1D9', '#75607C'],
  terracotta: ['#3B211B', '#8E4D38', '#FFF1E4', '#E7A95E', '#E8C0A3', '#8F6B5D'],
  slate: ['#18212B', '#344155', '#F4F0E8', '#B7C4D8', '#D7DDE7', '#697789'],
  sage: ['#E6E8D8', '#C3CBB1', '#1F2A1F', '#6D7F45', '#52613C', '#A8B092'],
  sand: ['#EFE4CE', '#CBAF82', '#2A241B', '#B06A3B', '#6D5940', '#BAA783'],
  rose: ['#2B1820', '#693345', '#FFF1F4', '#E6A0A8', '#E7C3C8', '#78535D'],
  midnight: ['#07111F', '#142B46', '#EFF6FF', '#D6B15E', '#C9D8E6', '#465C78']
}

function clamp(value, min, max) { return Math.max(min, Math.min(max, value)) }
function leap(year) { return year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0) }
function monthDays(year, month) { return month === 2 && leap(year) ? 29 : DAYS[month - 1] }
function parseDate(value) {
  const match = String(value || '').match(/^(\d{4})-(\d{2})-(\d{2})/)
  if (!match) return null
  const y = Number(match[1]), m = Number(match[2]), d = Number(match[3])
  if (m < 1 || m > 12 || d < 1 || d > monthDays(y, m)) return null
  return { y, m, d }
}
function dayOfYear(date) {
  let total = date.d
  for (let month = 1; month < date.m; month++) total += monthDays(date.y, month)
  return total
}
function utcDay(date) { return Math.floor(Date.UTC(date.y, date.m - 1, date.d) / 86400000) }
function validColor(value, fallback) { return /^#[0-9a-fA-F]{6}$/.test(String(value || '').trim()) ? String(value).trim() : fallback }
function percent(value) { return (Math.round(value * 10) / 10).toFixed(1) + '%' }
function wrap(value, maxChars) {
  const words = String(value || '').trim().replace(/\s+/g, ' ').split(' ')
  const lines = [], current = []
  for (const word of words) {
    const next = current.concat(word).join(' ')
    if (next.length > maxChars && current.length) { lines.push(current.join(' ')); current.length = 0 }
    current.push(word)
    if (lines.length === 2) break
  }
  if (current.length && lines.length < 3) lines.push(current.join(' '))
  return lines.slice(0, 3)
}

function Dot({ x, y, r, state, colors }) {
  if (state === 'today') return <g><circle cx={x} cy={y} r={r * 1.85} fill="none" stroke={colors.accent} strokeWidth={Math.max(1.2, r * 0.45)} /><circle cx={x} cy={y} r={r * 0.82} fill={colors.accent} /></g>
  return <circle cx={x} cy={y} r={r} fill={state === 'done' ? colors.completed : colors.remaining} />
}

export function get(app, context) {
  const W = context?.imageWidth ?? app.frame.width
  const H = context?.imageHeight ?? app.frame.height
  const unit = Math.min(W, H) / 100
  const today = parseDate(app.config.currentDate)
  const birth = parseDate(app.config.birthDate)
  const mode = app.config.mode === 'life' ? 'life' : 'year'
  const themeName = THEMES[app.config.theme] ? app.config.theme : 'ember'
  const palette = THEMES[themeName]
  const custom = themeName === 'custom'
  const colors = {
    start: custom ? validColor(app.config.startColor, palette[0]) : palette[0], end: custom ? validColor(app.config.endColor, palette[1]) : palette[1],
    text: custom ? validColor(app.config.textColor, palette[2]) : palette[2], accent: custom ? validColor(app.config.accentColor, palette[3]) : palette[3],
    completed: custom ? validColor(app.config.completedColor, palette[4]) : palette[4], remaining: custom ? validColor(app.config.remainingColor, palette[5]) : palette[5]
  }
  const margin = clamp(Math.min(W, H) * 0.045, 14, 56)
  if (!today || (mode === 'life' && !birth)) {
    const message = !today ? 'The clock value is unavailable.' : 'Use the Birth date field to start the life calendar.'
    return <svg width={W} height={H} viewBox={`0 0 ${W} ${H}`}><defs><linearGradient id="bg" gradientUnits="userSpaceOnUse" x1="0" y1="0" x2={W} y2={H}><stop offset="0" stopColor={colors.start} /><stop offset="1" stopColor={colors.end} /></linearGradient></defs><rect width={W} height={H} fill="url(#bg)" /><text x={W / 2} y={H / 2 - unit * 3} textAnchor="middle" fontFamily="PT Sans" fontWeight="700" fontSize={unit * 8} fill={colors.text}>Set a birth date</text><text x={W / 2} y={H / 2 + unit * 4} textAnchor="middle" fontFamily="PT Sans" fontSize={unit * 3.5} fill={colors.text}>{message}</text></svg>
  }

  const portrait = H > W
  const copyW = portrait ? W - margin * 2 : W * 0.31 - margin
  const gridX = portrait ? margin : W * 0.33
  const gridY = portrait ? H * 0.30 : margin
  const gridW = portrait ? W - margin * 2 : W - gridX - margin
  const gridH = portrait ? H - gridY - margin * 1.7 : H - margin * 2
  const dots = []
  let stat

  if (mode === 'year') {
    const current = dayOfYear(today), total = leap(today.y) ? 366 : 365
    const labelW = Math.min(gridW * 0.13, unit * 9), gap = unit * 0.8
    const pitch = Math.min((gridW - labelW - gap) / 31, gridH / 12)
    const r = clamp(pitch * 0.28, 1.4, unit * 1.2)
    const x0 = gridX + labelW + gap + (gridW - labelW - gap - pitch * 31) / 2 + pitch / 2
    const y0 = gridY + (gridH - pitch * 12) / 2 + pitch / 2
    let count = 0
    for (let month = 1; month <= 12; month++) {
      const y = y0 + (month - 1) * pitch
      dots.push(<text key={`m${month}`} x={gridX} y={y + pitch * 0.16} fontFamily="PT Sans" fontSize={clamp(pitch * 0.42, unit * 1.7, unit * 2.8)} fill={colors.text}>{MONTHS[month - 1]}</text>)
      for (let day = 1; day <= monthDays(today.y, month); day++) { count++; dots.push(<Dot key={`${month}-${day}`} x={x0 + (day - 1) * pitch} y={y} r={r} state={count < current ? 'done' : count === current ? 'today' : 'future'} colors={colors} />) }
    }
    stat = { pct: percent(current / total * 100), caption: `Day ${current} of ${total}`, kicker: `${today.y} YEAR PROGRESS`, foot: 'Each dot is one day. The ring is today.' }
  } else {
    const years = clamp(Math.round(Number(app.config.lifeExpectancyYears) || 80), 1, 130)
    const total = Math.max(52, Math.round(years * 52)), lived = clamp(Math.floor((utcDay(today) - utcDay(birth)) / 7), 0, total)
    const cols = Math.ceil(Math.sqrt(total * gridW / gridH)), rows = Math.ceil(total / cols), pitch = Math.min(gridW / cols, gridH / rows), r = clamp(pitch * 0.28, 0.75, unit * 0.95)
    const x0 = gridX + (gridW - pitch * cols) / 2 + pitch / 2, y0 = gridY + (gridH - pitch * rows) / 2 + pitch / 2
    for (let i = 0; i < total; i++) dots.push(<Dot key={i} x={x0 + (i % cols) * pitch} y={y0 + Math.floor(i / cols) * pitch} r={r} state={i < lived ? 'done' : i === lived ? 'today' : 'future'} colors={colors} />)
    stat = { pct: percent(lived / total * 100), caption: `Week ${lived + 1} of ${total}`, kicker: `${years} YEAR LIFE CALENDAR`, foot: 'Each dot is one week. The ring is now.' }
  }

  const title = String(app.config.title || 'Memento mori'), subtitle = String(app.config.subtitle || '')
  const titleSize = clamp(copyW * (portrait ? 0.07 : 0.11), unit * 4.4, unit * 9.5)
  const pctSize = clamp(copyW * (portrait ? 0.17 : 0.23), unit * 8.5, unit * 22)
  const bodySize = clamp(copyW * 0.046, unit * 3.2, unit * 5)
  const anchor = portrait ? 'middle' : 'start', copyX = portrait ? W / 2 : margin, copyY = portrait ? margin + titleSize : margin + titleSize
  const lines = wrap(subtitle, Math.max(12, Math.floor(copyW / (bodySize * 0.55))))
  return <svg width={W} height={H} viewBox={`0 0 ${W} ${H}`}><defs><linearGradient id="bg" gradientUnits="userSpaceOnUse" x1="0" y1="0" x2={W} y2={H}><stop offset="0" stopColor={colors.start} /><stop offset="1" stopColor={colors.end} /></linearGradient></defs><rect width={W} height={H} fill="url(#bg)" />{dots}<text x={copyX} y={copyY} textAnchor={anchor} fontFamily="PT Sans" fontWeight="700" fontSize={titleSize} fill={colors.text}>{title}</text><text x={copyX} y={copyY + unit * 5} textAnchor={anchor} fontFamily="PT Sans" fontSize={unit * 2.8} fill={colors.accent}>{stat.kicker}</text><text x={copyX} y={copyY + pctSize + unit * 7} textAnchor={anchor} fontFamily="PT Sans" fontWeight="700" fontSize={pctSize} fill={colors.text}>{stat.pct}</text><text x={copyX} y={copyY + pctSize + unit * 12} textAnchor={anchor} fontFamily="PT Sans" fontSize={unit * 2.8} fill={colors.text}>{stat.caption}</text>{!portrait && lines.map((line, i) => <text key={i} x={copyX} y={copyY + pctSize + unit * (19 + i * 5)} textAnchor="start" fontFamily="PT Sans" fontSize={bodySize} fill={colors.text}>{line}</text>)}<text x={W - margin} y={H - margin * 0.45} textAnchor="end" fontFamily="PT Sans" fontSize={clamp(unit * 2.3, 10, 18)} fill={colors.text}>{stat.foot}</text></svg>
}
